/* Event fire macro */
/* Used within role functions: FIRE_EVENT(ctx, EVENT_XXX_YYY); */
#define FIRE_EVENT(ctx, evt)  do { \
    (ctx)->pending_event = (uint16_t)(evt); \
    (ctx)->pending_event_valid = true; \
} while(0)

